f=open('[REDACTED LOCAL PATH]')
entry={}
cur=None
started=False
mapping={}
for line in f:
    if line.startswith('ID   '):
        if cur and cur in names:
            mapping[cur]=entry
        cur=line[5:].strip().split(' ')[0]
        entry={'ID':cur}
    elif cur in names:
        if line.startswith('AC   '):
            entry['AC']=line[5:].strip()
