            entry.setdefault('IGSR',[]).append(line.strip())
    else:
        # still need advance; no capture
        pass
if cur in names: mapping[cur]=entry
for n in sorted(names):
    e=mapping.get(n,{})
    print(n, e.get('AC'), e.get('IGSR'))
